head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[group > E > onmouseup]<br/>컴포넌트 영역에서 마우스 버튼을 때는 순간 발생합니다.",
    "validation" : [
        "컴포넌트 영역에서 마우스 왼쪽 버튼을 때는 순간 이벤트가 발생하여야 합니다.",
        "컴포넌트 영역에서 마우스 오른쪽 버튼을 때는 순간 이벤트가 발생하여야 합니다.",
        "컴포넌트 영역에서 마우스 휠 버튼을 때는 순간 이벤트가 발생하여야 합니다.",
        "자식 컴포넌트에서 onmouseup 이벤트가 발생하면 Group 컴포넌트로 버블링됩니다.",        
    ]
} 



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출    
    $c.gcm.createBasicGroup('', 'ev:onmouseup="scwin.target1_onmouseup"');    
}
